using Microsoft.EntityFrameworkCore;using EMedicine.Api.Models;
namespace EMedicine.Api.Data;
public class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<Medicine> Medicines=>Set<Medicine>();public DbSet<CartItem> Cart=>Set<CartItem>();public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderItem> OrderItems=>Set<OrderItem>();protected override void OnModelCreating(ModelBuilder b){b.Entity<AppUser>().Property(x=>x.Fund).HasPrecision(18,2);b.Entity<AppUser>().HasIndex(x=>x.Email).IsUnique();b.Entity<CartItem>().HasIndex(x=>new{x.UserId,x.MedicineId}).IsUnique();b.Entity<Medicine>().Property(x=>x.UnitPrice).HasPrecision(18,2);b.Entity<Medicine>().Property(x=>x.Discount).HasPrecision(5,2);b.Entity<Order>().Property(x=>x.Total).HasPrecision(18,2);b.Entity<OrderItem>().Property(x=>x.UnitPrice).HasPrecision(18,2);b.Entity<OrderItem>().Property(x=>x.Discount).HasPrecision(5,2);b.Entity<OrderItem>().Property(x=>x.TotalPrice).HasPrecision(18,2);}}
